// Validar datos requeridos
const body = $input.item.json.body;
const errors = [];

if (!body.guest_email) {
  errors.push('guest_email es requerido');
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.guest_email)) {
  errors.push('guest_email no es un email válido');
}

if (!body.reservation_id) errors.push('reservation_id es requerido');
if (!body.guest_name) errors.push('guest_name es requerido');
if (!body.check_in_date) errors.push('check_in_date es requerido');
if (!body.room_type) errors.push('room_type es requerido');
if (!body.group_size) errors.push('group_size es requerido');

// Validar formato de reservation_id (DDMMYYYYHHMMSS)
if (body.reservation_id && !/^\d{14}$/.test(body.reservation_id)) {
  errors.push('reservation_id debe tener formato DDMMYYYYHHMMSS (14 dígitos)');
}

if (errors.length > 0) {
  return {
    json: {
      success: false,
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Datos inválidos',
        details: errors
      },
      _continue: false
    }
  };
}

return {
  json: {
    ...body,
    _continue: true
  }
};

// Construir HTML del email de confirmación
const data = $input.item.json;

// Formatear folio para mostrar con guiones para legibilidad
const folio = data.reservation_id;
const folioFormateado = `${folio.substring(0,2)}-${folio.substring(2,4)}-${folio.substring(4,8)}-${folio.substring(8,10)}-${folio.substring(10,12)}-${folio.substring(12,14)}`;

const htmlContent = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    .container { max-width: 600px; margin: 0 auto; padding: 20px; }
    .header { background: #27ae60; color: white; padding: 30px; text-align: center; }
    .content { padding: 30px; background: #f9f9f9; }
    .folio-box { background: #fff; border: 3px solid #27ae60; padding: 20px; margin: 20px 0; text-align: center; border-radius: 5px; }
    .folio-label { font-size: 14px; color: #7f8c8d; text-transform: uppercase; margin-bottom: 10px; }
    .folio-number { font-size: 28px; font-weight: bold; color: #27ae60; letter-spacing: 2px; }
    .detail { margin: 15px 0; padding: 10px; background: white; border-left: 4px solid #3498db; }
    .label { font-weight: bold; color: #2c3e50; }
    .value { color: #34495e; }
    .important { background: #fff3cd; border-left-color: #ffc107; padding: 15px; margin: 20px 0; }
    .footer { text-align: center; padding: 20px; color: #7f8c8d; font-size: 12px; }
    .checkmark { color: #27ae60; font-size: 48px; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div class="checkmark">✓</div>
      <h1>¡Reservación Confirmada!</h1>
    </div>
    <div class="content">
      <p>Estimado/a <strong>${data.guest_name}</strong>,</p>
      <p>Tu reservación ha sido confirmada exitosamente. A continuación encontrarás los detalles:</p>

      <div class="folio-box">
        <div class="folio-label">Tu Folio de Reservación</div>
        <div class="folio-number">${folioFormateado}</div>
        <p style="font-size: 12px; color: #7f8c8d; margin-top: 10px;">Guarda este número, lo necesitarás para tu check-in</p>
      </div>

      <div class="detail">
        <span class="label">Fecha de entrada:</span> <span class="value">${data.check_in_date}</span>
      </div>
      <div class="detail">
        <span class="label">Tipo de habitación:</span> <span class="value">${data.room_type}</span>
      </div>
      <div class="detail">
        <span class="label">Número de personas:</span> <span class="value">${data.group_size}</span>
      </div>

      <div class="important">
        <strong>⚠️ Importante para tu check-in:</strong>
        <ul>
          <li>Llega con tu folio: <strong>${folioFormateado}</strong></li>
          <li>Presenta una identificación oficial</li>
          <li>El check-in es a partir de las 15:00 hrs</li>
          <li>El check-out es hasta las 12:00 hrs</li>
        </ul>
      </div>

      <p>Estamos emocionados de recibirte. Si tienes alguna pregunta o necesitas hacer cambios a tu reservación, no dudes en contactarnos.</p>

      <p style="margin-top: 30px;"><strong>¡Nos vemos pronto!</strong></p>
    </div>
    <div class="footer">
      <p>¿Necesitas ayuda? Contáctanos al teléfono del hotel</p>
      <p>&copy; ${new Date().getFullYear()} Hotel. Todos los derechos reservados.</p>
    </div>
  </div>
</body>
</html>
`;

return {
  json: {
    ...data,
    html: htmlContent,
    folio_formateado: folioFormateado
  }
};

// Formatear respuesta exitosa
